/**
 * The only component that renders icons (`design/components/icon.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/icon.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { derived } from '../conventions/cells'
import { MEMBER_PROVIDERS, useMember } from '../conventions/member'
import { Glyph } from './Glyph'
import type { IconRole } from '@polymorph/engine'
import styles from './icon.module.css'

/** The only component that renders icons: the inputs it takes, by the React member's prop names. */
export interface IconProps {
  /**
   * Accessible name: set it for a meaningful icon (`role="img"` + `aria-label`), omit it for a
   * decorative one (`aria-hidden`), and omit it inside an icon-only Button, which uses its own
   * `label`.
   */
  label?: string
  /**
   * A meaning from the closed role enum, never a glyph name.
   */
  name: IconRole
  size?: 'sm' | 'md' | 'lg'
}

/** The only component that renders icons. */
@Component({
  selector: 'pm-icon',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Glyph],
  // prettier-ignore
  template: `<svg
[pmGlyph]="e1()"
[attr.class]="e2()"
[attr.data-size]="e3()"
[attr.data-icon]="e1()"
[attr.aria-hidden]="e4()"
[attr.role]="e5()"
[attr.aria-label]="e6()"
data-member="icon"
></svg>`,
})
export class Icon {
  /**
   * Accessible name: set it for a meaningful icon (`role="img"` + `aria-label`), omit it for a
   * decorative one (`aria-hidden`), and omit it inside an icon-only Button, which uses its own
   * `label`.
   */
  readonly label = input<IconProps['label']>(undefined)
  /**
   * A meaning from the closed role enum, never a glyph name.
   */
  readonly name = input.required<IconProps['name']>()
  readonly size = input<Exclude<IconProps['size'], undefined>, IconProps['size']>('md', {
    transform: (value: IconProps['size']) => (value === undefined ? 'md' : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: { label: () => this.label(), name: () => this.name(), size: () => this.size() },
  })
  protected readonly $p = this.$.props
  protected readonly meaningful = derived(() => this.$p.label !== undefined)

  protected e1() {
    return this.$p.name
  }

  protected e2() {
    return styles.icon
  }

  protected e3() {
    return this.$p.size
  }

  protected e4() {
    return !this.meaningful.value ? true : undefined
  }

  protected e5() {
    return this.meaningful.value ? 'img' : undefined
  }

  protected e6() {
    return this.$p.label
  }
}
